/** Fixed original passive Writer exports, CC0-1.0; embedded DejaVu fonts retain their licence. */
const originals: Readonly<Record<string, string>> = {
  D01: '',
  D02: '',
  D03: '',
  D04: '',
  D05: '',
  D06: '',
  D07: '',
  D08: '',
  D09: '',
  D10: '',
  D11: '',
  D12: '',
};
export function documentPdf(id: string): Uint8Array {
  const base64 = originals[id];
  if (!base64) throw new Error('Неизвестный образец документа.');
  return Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
}
export function validateDocumentPdf(bytes: Uint8Array): void {
  if (
    !Object.keys(originals).some((id) => {
      const expected = documentPdf(id);
      return (
        bytes.length === expected.length &&
        bytes.every((byte, i) => byte === expected[i])
      );
    })
  )
    throw new Error('PDF не соответствует авторскому образцу.');
}
